'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icons={plane:'<path d="m3 10 7 2 5 8 2-1-2-8 5-7-1-1-7 5-8-2z"/><path d="m6 14-3 4 4-1"/>',steering:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2"/><path d="m4 9 6 2m4 0 6-2m-8 5v7"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',sparkle:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',heart:'<path d="M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-6 6 8 15 8 15S26 11 20 5Z"/>',check:'<path d="m5 12 4 4L19 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',phone:'<path d="m5 3 4 4-2 3c2 3 4 5 7 7l3-2 4 4c-2 4-5 3-9 1S4 14 2 9s0-7 3-6Z"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.check}</svg>`;
function hydrateIcons(root=document){$$('[data-icon]',root).forEach(e=>e.innerHTML=icon(e.dataset.icon));}
const escapeHtml=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(v);
const dateValue=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=dateValue(new Date());const tomorrowDate=new Date();tomorrowDate.setDate(tomorrowDate.getDate()+1);const tomorrow=dateValue(tomorrowDate);
const locations=['Malta Airport (MLA)','Valletta','St Julian’s','Sliema','Mdina','Mellieħa','Bugibba / Qawra','Golden Bay'];
const options=(arr,selected)=>arr.map(x=>`<option value="${escapeHtml(x)}" ${x===selected?'selected':''}>${escapeHtml(x)}</option>`).join('');
const field=(label,control,extra='')=>`<div class="field ${extra}"><label for="${control.match(/id="([^"]+)"/)?.[1]||''}">${label}</label>${control}</div>`;
const journeyDrafts={};
function captureJourneyDraft(){const f=$('#journey-form');if(f&&$('#booking-fields').children.length)journeyDrafts[service]=Object.fromEntries(new FormData(f));}
let service='transfer', direction='one-way', booking={}, selectedVehicle='executive', chosenTour='heritage', payment='card', modalStep=1;
const tours={heritage:{title:'The timeless heart of Malta',route:'Valletta · Mdina',hours:4,price:160,img:'mdina.webp',description:'Take your time among Valletta’s grand streets and Mdina’s quiet lanes. This sample itinerary pairs Malta’s capital with its historic heart, with room for a coffee stop and your own discoveries.',stops:['Valletta waterfront & city gates','Free time to explore Valletta on foot','Mdina & Rabat','Return to your accommodation']},coast:{title:'A slower side of the island',route:'Blue Grotto · Marsaxlokk',hours:6,price:220,img:'tour-coast.webp',description:'Swap the rush for sea air, fishing harbours and limestone coastlines. This sample private itinerary lets you linger at the places you love. Boat trips depend on conditions and are arranged separately.',stops:['Blue Grotto viewpoint','Wied iż-Żurrieq coast','Marsaxlokk fishing village','Scenic stops & return to your accommodation']}};
const vehicles=[{id:'comfort',name:'Comfort',model:'Private saloon · or similar',pax:3,bags:2,mult:1,hour:40,img:'airport.webp'},{id:'executive',name:'Executive',model:'Mercedes E-Class · or similar',pax:3,bags:2,mult:1.45,hour:55,img:'executive.webp'},{id:'van',name:'Premium people carrier',model:'Spacious vehicle for families & groups',pax:7,bags:7,mult:1.9,hour:70,img:'fleet.webp'},{id:'minibus',name:'Private minibus',model:'Room for your whole group',pax:16,bags:16,mult:2.6,hour:95,img:'fleet.webp'}];
function notify(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),3300);}
function setService(next,scroll=false){captureJourneyDraft();service=next;$$('[data-tab]').forEach(el=>{const active=el.dataset.tab===service;el.setAttribute('aria-selected',active);el.tabIndex=active?0:-1;});$('#booking-fields').setAttribute('aria-labelledby','tab-'+service);$('#trip-options').hidden=service!=='transfer';renderFields();$$('.services-menu').forEach(el=>el.open=false);if(scroll)$('#booking').scrollIntoView({behavior:'smooth',block:'start'});}
function renderFields(){const area=$('#booking-fields');area.className='booking-fields';let html='';
  const dateField=field(service==='wedding'?'Your special date':'Pickup date',`<input type="date" id="journey-date" name="date" min="${today}" value="${tomorrow}" required>`);
  const timeField=field('Pickup time',`<input type="time" id="journey-time" name="time" value="10:00" required>`);
  const passengers=field('Passengers',`<select id="journey-passengers" name="passengers">${options(Array.from({length:16},(_,i)=>(i+1)+' passenger'+(i?'s':'')),'2 passengers')}</select>`);
  if(service==='transfer'){
    html=field('From',`<div class="input-icon">${icon('plane')}<select id="journey-from" name="from">${options(locations,locations[0])}</select></div>`)+field('To',`<div class="input-icon">${icon('pin')}<input id="journey-to" name="to" list="locations" placeholder="Hotel, address or destination" required autocomplete="off"></div><datalist id="locations">${locations.slice(1).map(x=>`<option value="${escapeHtml(x)}"></option>`).join('')}</datalist>`)+dateField+timeField+passengers;
    if(direction==='return'){area.classList.add('has-return');html+=`<div class="return-fields">${field('Return date',`<input type="date" id="return-date" name="returnDate" min="${today}" value="${tomorrow}" required>`)}${field('Return time',`<input type="time" id="return-time" name="returnTime" value="18:00" required>`)}</div>`;}
    html+='<button class="button button-dark find-journey" type="submit">Find my ride <span>↗</span></button>';
  }else if(service==='chauffeur'){
    area.classList.add('chauffeur-fields');html=field('Pickup location',`<input id="journey-from" name="from" placeholder="Hotel, address or location" required>`)+dateField+timeField+field('Duration',`<select id="journey-hours" name="hours">${options(['3 hours','4 hours','5 hours','6 hours','8 hours','10 hours'],'3 hours')}</select>`)+passengers+'<button class="button button-dark find-journey" type="submit">Find my chauffeur <span>↗</span></button>';
  }else if(service==='tour'){
    area.classList.add('tour-fields');html=field('Your experience',`<select id="journey-tour" name="tour"><option value="heritage">The timeless heart of Malta · 4h</option><option value="coast">A slower side of the island · 6h</option><option value="custom">Build my own private tour</option></select>`)+dateField+passengers+'<button class="button button-dark find-journey" type="submit">Explore my tour <span>↗</span></button>';
  }else{
    area.classList.add('wedding-fields');html=field('The occasion',`<select id="journey-occasion" name="occasion">${options(['Our wedding day','A special occasion','Vintage car experience'],'Our wedding day')}</select>`)+dateField+field('Your preferred style',`<select id="journey-car" name="car">${options(['Help me choose','Rolls-Royce','Bentley','Daimler','Cadillac'],'Help me choose')}</select>`)+ '<button class="button button-dark find-journey" type="submit">Check availability <span>↗</span></button>';
  }area.innerHTML=html;
  const draft=journeyDrafts[service];if(draft)$$('input,select',area).forEach(el=>{if(draft[el.name]!==undefined)el.value=draft[el.name];});
}
const dialog=$('#journey-dialog');
function openModal(html){$('#dialog-body').innerHTML=html;hydrateIcons($('#dialog-body'));if(!dialog.open){dialog.showModal();document.body.style.overflow='hidden';}dialog.scrollTop=0;const heading=$('h2',dialog);if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function closeModal(){dialog.close();document.body.style.overflow='';}
dialog.addEventListener('close',()=>document.body.style.overflow='');
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function dateLabel(value){return new Date(value+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function stepper(step){return `<div class="stepper" aria-label="Booking progress">${['Choose your vehicle','Journey details','Review & pay'].map((s,i)=>`<span class="${i+1===step?'active':i+1<step?'done':''}" ${i+1===step?'aria-current="step"':''}><b>${i+1<step?'✓':i+1}</b>${s}</span>`).join('')}</div>`;}
function routeSummary(){let title=booking.service==='tour'?tours[booking.tour].title:booking.service==='chauffeur'?`Chauffeur · ${booking.hours} hours`:`${booking.from} → ${booking.to}`;return `<div class="route-summary"><div><strong>${escapeHtml(title)}</strong><p>${dateLabel(booking.date)} · ${booking.time} · ${booking.passengers} passenger${booking.passengers>1?'s':''}</p></div><div>${booking.direction==='return'?`<strong>Return included</strong><p>${dateLabel(booking.returnDate)} · ${booking.returnTime}</p>`:'<strong>Private journey</strong><p>EUR · Illustrative pricing</p>'}</div></div>`;}
function transferBase(){const place=(booking.to+' '+booking.from).toLowerCase();return /mellie|golden/.test(place)?55:/bugibba|qawra/.test(place)?45:/julian|sliema/.test(place)?40:35;}
function vehiclePrice(v){if(booking.service==='chauffeur')return v.hour*(booking.hours+(booking.extraHours||0));if(booking.service==='tour')return tours[booking.tour].price*(v.id==='comfort'?1:v.id==='executive'?1.25:v.id==='van'?1.5:2);return Math.round(transferBase()*v.mult)*(booking.direction==='return'?2:1);}
function currentVehicle(){return vehicles.find(v=>v.id===selectedVehicle)||vehicles[0];}
function totals(){const base=vehiclePrice(currentVehicle());const extras=(booking.childSeat?8:0)+(booking.booster?5:0);return {base,extras,total:base+extras};}
function showVehicles(){modalStep=1;const available=vehicles.filter(v=>v.pax>=booking.passengers&&v.bags>=(booking.bags||0));if(!available.some(v=>v.id===selectedVehicle))selectedVehicle=available[0]?.id||'';
  openModal(`<div class="dialog-content">${stepper(1)}<h2 id="dialog-title">A little comfort goes a long way.</h2><p class="intro">Choose the space and style that suit your journey. Your vehicle is private to your group.</p>${routeSummary()}<div class="field"><label for="luggage-count">Large suitcases</label><select id="luggage-count" style="max-width:180px">${Array.from({length:9},(_,i)=>`<option value="${i}" ${i===(booking.bags??1)?'selected':''}>${i} suitcase${i!==1?'s':''}</option>`).join('')}</select></div><form id="vehicle-form"><div class="vehicle-list">${available.map(v=>`<label class="vehicle-option"><img src="assets/${v.img}" alt="${v.name} vehicle illustration"><div><h3>${v.name}</h3><p>${v.model}</p><div class="vehicle-meta"><span>Up to ${v.pax} passengers</span><span>${v.bags} large cases</span></div></div><div class="vehicle-price"><strong>${money(vehiclePrice(v))}</strong><small>${booking.service==='chauffeur'?`${money(v.hour)} / hour`:'total · per vehicle'}</small><input type="radio" name="vehicle" value="${v.id}" ${selectedVehicle===v.id?'checked':''} aria-label="Select ${v.name}" required></div></label>`).join('')||'<div class="notice">Your group needs a tailored vehicle arrangement. Please call our team to confirm suitable capacity.</div>'}</div><p class="small-note">Sample fares and capacities for design review. Vehicle model, availability, inclusions and final pricing are confirmed by John’s. ${booking.service==='chauffeur'?'A 3-hour minimum is used in this concept. Additional hours are shown before checkout.':''}</p><div class="dialog-actions"><button type="button" class="text-button" data-action="close">← Edit my journey</button>${available.length?'<button class="button button-dark" type="submit">Journey details <span>→</span></button>':'<a class="button button-dark" href="tel:+35622982123">Contact the team <span>↗</span></a>'}</div></form></div>`);
}
function showDetails(){modalStep=2;const flight=booking.service==='transfer'?field('Flight number'+(booking.from===locations[0]?' *':''),`<input id="flight-number" name="flight" placeholder="e.g. KM 101" value="${escapeHtml(booking.flight||'')}" ${booking.from===locations[0]?'required':''}>`):'';
 openModal(`<div class="dialog-content">${stepper(2)}<h2 id="dialog-title">The details make the difference.</h2><p class="intro">No account needed. Just a few details so we can take good care of you.</p>${routeSummary()}<form id="details-form"><div class="form-grid">${field('First name *',`<input id="first-name" name="firstName" autocomplete="given-name" value="${escapeHtml(booking.firstName||'')}" required maxlength="80">`)}${field('Last name *',`<input id="last-name" name="lastName" autocomplete="family-name" value="${escapeHtml(booking.lastName||'')}" required maxlength="80">`)}${field('Email address *',`<input id="guest-email" name="email" type="email" autocomplete="email" value="${escapeHtml(booking.email||'')}" required maxlength="200">`)}${field('Mobile number with country code *',`<input id="guest-phone" name="phone" type="tel" autocomplete="tel" placeholder="+356 …" value="${escapeHtml(booking.phone||'')}" required minlength="6" maxlength="30">`)}${field(booking.service==='tour'?'Hotel / pickup address *':'Full pickup / drop-off address *',`<input id="guest-address" name="address" placeholder="Hotel name, street and locality" value="${escapeHtml(booking.address||'')}" required maxlength="250">`,'wide')}${flight}${booking.service==='chauffeur'?field('Planned extra hours',`<select id="extra-hours" name="extraHours">${[0,1,2,3].map(n=>`<option value="${n}" ${n===(booking.extraHours||0)?'selected':''}>${n?'Add '+n+' hour'+(n>1?'s':''):'No extra hours'}</option>`).join('')}</select>`):''}${field('Anything we should know?',`<textarea id="guest-notes" name="notes" placeholder="Accessibility requirements, extra luggage, preferred stops…" maxlength="1000">${escapeHtml(booking.notes||'')}</textarea>`,'wide')}</div><h3 class="subheading">Make it yours</h3><div class="extra-grid"><label class="extra-option"><input type="checkbox" name="childSeat" ${booking.childSeat?'checked':''}><span>Child seat<small>+€8 · sample</small></span></label><label class="extra-option"><input type="checkbox" name="booster" ${booking.booster?'checked':''}><span>Booster seat<small>+€5 · sample</small></span></label><label class="extra-option"><input type="checkbox" name="invoice" ${booking.invoice?'checked':''}><span>VAT invoice<small>Add business details</small></span></label></div><div id="invoice-fields" class="form-grid" ${booking.invoice?'':'hidden'}>${field('Business name *',`<input id="business-name" name="businessName" value="${escapeHtml(booking.businessName||'')}" ${booking.invoice?'required':''}>`)}${field('VAT number *',`<input id="vat-number" name="vatNumber" value="${escapeHtml(booking.vatNumber||'')}" ${booking.invoice?'required':''}>`)}</div><p class="small-note" style="margin-top:14px">Child seat suitability and any accessibility needs are confirmed by the team. Airport meet & greet is included in this concept.</p><div class="dialog-actions"><button type="button" class="text-button" data-action="back-vehicles">← Vehicles</button><button class="button button-dark" type="submit">Review & pay <span>→</span></button></div></form></div>`);
}
function showCheckout(){modalStep=3;const t=totals(),v=currentVehicle();const sampleVAT=t.total-t.total/1.18;
 openModal(`<div class="dialog-content">${stepper(3)}<h2 id="dialog-title">Your journey, all taken care of.</h2><p class="intro">One final look. Your booking is always in euros, with everything set out before you pay.</p><div class="checkout-layout"><div><h3 class="subheading" style="margin-top:0">Your details</h3><div class="route-summary"><div><strong>${escapeHtml(booking.firstName)} ${escapeHtml(booking.lastName)}</strong><p>${escapeHtml(booking.email)}<br>${escapeHtml(booking.phone)}</p><p>${escapeHtml(booking.address)}${booking.flight?'<br>Flight: '+escapeHtml(booking.flight):''}</p></div></div><button class="underlink" data-action="back-details">Edit details <span>↗</span></button><h3 class="subheading">Choose how to pay</h3><div class="pay-options"><button class="pay-option ${payment==='card'?'active':''}" data-pay="card" aria-pressed="${payment==='card'}">Credit / debit card</button><button class="pay-option ${payment==='apple'?'active':''}" data-pay="apple" aria-pressed="${payment==='apple'}" aria-label="Apple Pay"><img class="payment-logo apple-pay" src="assets/payments/apple-Apple_Pay_Mark_RGB_041619.svg" alt="Apple Pay"></button><button class="pay-option ${payment==='google'?'active':''}" data-pay="google" aria-pressed="${payment==='google'}" aria-label="Google Pay"><img class="payment-logo google-pay" src="assets/payments/google-google-pay-mark_800.svg" alt="Google Pay"></button></div><div class="card-preview"><strong>${payment==='card'?'Secure card payment':payment==='apple'?'Apple Pay':'Google Pay'} · preview</strong><p>A Trust Payments secure checkout would appear here. Wallets are shown on supported devices after merchant enablement. No payment details are collected in this demo.</p></div><label class="check-label"><input type="checkbox" id="pending-preview"><span>Preview a temporary booking-system delay.</span></label></div><aside class="review-card"><h3>Your journey</h3><p class="small-note">${escapeHtml(booking.service==='tour'?tours[booking.tour].title:booking.from+(booking.to?' → '+booking.to:''))}<br>${dateLabel(booking.date)} · ${booking.time}<br>${booking.passengers} passengers · ${booking.bags??1} suitcase(s)<br>${v.name}${booking.service==='chauffeur'?` · ${booking.hours+(booking.extraHours||0)} hours`:''}${booking.direction==='return'?`<br>Return: ${dateLabel(booking.returnDate)} · ${booking.returnTime}`:''}</p><div class="price-row"><span>Private ${booking.service==='tour'?'tour':booking.service==='chauffeur'?'chauffeur':'transfer'}</span><strong>${money(t.base)}</strong></div>${booking.childSeat?'<div class="price-row"><span>Child seat</span><strong>€8.00</strong></div>':''}${booking.booster?'<div class="price-row"><span>Booster seat</span><strong>€5.00</strong></div>':''}<div class="price-row"><span>Net amount (illustrative)</span><span>${money(t.total-sampleVAT)}</span></div><div class="price-row"><span>VAT (illustrative 18%)</span><span>${money(sampleVAT)}</span></div><div class="price-row total"><span>Total, VAT included</span><span>${money(t.total)}</span></div><p class="small-note">Sample tax calculation only. Applicable VAT treatment, rates and invoice issuer require confirmation before launch. Your sample receipt uses this same total.</p><div class="notice">Design preview only. No booking is sent, no card is charged and no emails are issued.</div></aside></div><form id="checkout-form"><label class="check-label"><input type="checkbox" name="terms" required><span>I have reviewed the <button type="button" class="text-button" data-action="checkout-terms">booking terms</button> and understand this is a demonstration.</span></label><div class="dialog-actions"><button type="button" class="text-button" data-action="back-details">← Journey details</button><button class="button button-dark" type="submit">Preview confirmation <span>→</span></button></div></form></div>`);
}
function showConfirmation(pending){const t=totals();openModal(`<div class="dialog-content"><div class="success-state"><div class="success-icon">${pending?'◷':'✓'}</div><span class="eyebrow">${pending?'YOUR REQUEST IS SAFELY HELD':'A GOOD JOURNEY STARTS HERE'}</span><h2 id="dialog-title">${pending?'We’re finalising your journey.':'You’re on your way.'}</h2><p>${pending?'If the booking system were temporarily unavailable, your request would be held for the team to confirm. A pending request must never be shown as a confirmed vehicle.':'This is a preview of the confirmation your customer would see after successful payment and booking-system acceptance.'}</p><div class="reference">DEMONSTRATION REFERENCE<strong>JM-DEMO-2601</strong>${pending?'Status: awaiting team confirmation':'Status: confirmed (demo)'}</div>${routeSummary()}<div class="confirmation-grid"><div><strong>Everything in one email</strong><p>Journey details, meeting instructions, booking reference and receipt go to the customer and John’s team after launch.</p></div><div><strong>A clear record</strong><p>Demo total: ${money(t.total)}. The receipt and VAT invoice use the same booking record.</p></div><div><strong>Help when you need it</strong><p>Call +356 2298 2123. Quote your booking reference for assistance.</p></div></div><p class="small-note">No booking, payment or email was created. Live confirmation and status updates depend on the codevlabs integration.</p><button class="button button-dark" data-action="receipt">View sample receipt <span>↗</span></button><button class="text-button" data-action="close" style="display:block;margin:18px auto 0">Back to John’s Malta</button></div></div>`);}
function showReceipt(){const t=totals();openModal(`<div class="dialog-content legal-content"><span class="eyebrow">SAMPLE · NOT A FISCAL DOCUMENT</span><h2 id="dialog-title">Your journey receipt.</h2><div class="route-summary"><div><strong>John’s · JG Drive Services Ltd</strong><p>Ħamrun, Malta · info@johns.com.mt</p></div><div><strong>JM-DEMO-2601</strong><p>${dateLabel(booking.date)}</p></div></div><p>Prepared for ${escapeHtml(booking.firstName)} ${escapeHtml(booking.lastName)}${booking.businessName?'<br>'+escapeHtml(booking.businessName)+' · '+escapeHtml(booking.vatNumber):''}.</p><div class="review-card"><div class="price-row"><span>Journey with ${currentVehicle().name}</span><span>${money(t.base)}</span></div><div class="price-row"><span>Selected extras</span><span>${money(t.extras)}</span></div><div class="price-row"><span>Net (illustrative)</span><span>${money(t.total/1.18)}</span></div><div class="price-row"><span>VAT (illustrative 18%)</span><span>${money(t.total-t.total/1.18)}</span></div><div class="price-row total"><span>Sample total</span><span>${money(t.total)}</span></div></div><p>Tax treatment, supplier registration details and fiscal invoice issuer must be confirmed for the production system. No payment has been taken.</p><div class="dialog-actions"><button class="text-button" data-action="back-confirmation">← Confirmation</button><button class="button button-dark" data-action="close">Done <span>✓</span></button></div></div>`);}
function showTours(){openModal(`<div class="dialog-content"><span class="eyebrow">THE ISLAND, AT YOUR PACE</span><h2 id="dialog-title">A little more Malta.</h2><p class="intro">Choose a private journey or tell us what your perfect day looks like. Sample itineraries and prices.</p><div class="tour-options">${Object.entries(tours).map(([id,t])=>`<button class="tour-option" data-tour="${id}"><img src="assets/${t.img}" alt="${t.route}"><strong>${t.title}</strong><span>${t.route}</span><span>${t.hours} hours · From ${money(t.price)} / vehicle ↗</span></button>`).join('')}</div><div class="notice">Your pickup, your pace. Attraction admission, boats, meals and licensed guiding are excluded from sample fares unless explicitly added.</div><button class="button button-dark" data-action="custom-tour">Build your own tour <span>↗</span></button></div>`);}
function showTour(id){chosenTour=id;const t=tours[id];const tourDate=booking.service==='tour'?booking.date:tomorrow;const tourPax=booking.service==='tour'?String(booking.passengers):'2';openModal(`<div class="dialog-content"><span class="eyebrow">PRIVATE TOUR · ${t.hours} HOURS</span><h2 id="dialog-title">${t.title}</h2><img class="tour-detail-photo" src="assets/${t.img}" alt="${t.route}"><p class="intro">${t.description}</p><div class="tour-highlights"><span>✓ Private driver & vehicle</span><span>✓ Hotel pickup & return</span><span>✓ Flexible stops</span></div><h3 class="subheading">An idea of your day</h3><ol class="small-note">${t.stops.map(s=>`<li>${s}</li>`).join('')}</ol><div class="notice">Illustrative itinerary. Admission, boat tickets, meals and licensed guides are excluded. Final tour scope, availability and prices require confirmation.</div><form id="tour-book-form"><div class="form-grid">${field('Date *',`<input type="date" id="tour-date" name="date" min="${today}" value="${tourDate}" required>`)}${field('Pickup time *',`<input type="time" id="tour-time" name="time" value="09:00" required>`)}${field('Passengers',`<select id="tour-pax" name="passengers">${options(Array.from({length:16},(_,i)=>String(i+1)),tourPax)}</select>`)}${field('Pickup location *',`<input id="tour-pickup" name="from" placeholder="Hotel, address or location" required>`)}</div><div class="dialog-actions"><button type="button" class="text-button" data-action="all-tours">← All tours</button><button class="button button-dark" type="submit">Choose vehicle <span>→</span></button></div></form></div>`);}
function showEnquiry(type){const wedding=type==='wedding';const date=booking.date||tomorrow;openModal(`<div class="dialog-content"><span class="eyebrow">${wedding?'SOMETHING TIMELESS. SOMETHING YOURS.':'LET’S MAKE IT PERSONAL'}</span><h2 id="dialog-title">${wedding?'A beautiful arrival starts here.':'Your Malta. Your way.'}</h2><p class="intro">${wedding?'Tell us about your occasion and preferred car. The team confirms availability and your quote before a deposit is requested.':'Share your interests, must-see places and pace. The team will shape an itinerary and quote around you.'}</p>${wedding?'<img class="tour-detail-photo" src="assets/wedding.webp" alt="John’s vintage wedding car by the sea">':''}<form id="enquiry-form" data-type="${type}"><div class="form-grid">${field('Your name *',`<input id="enquiry-name" name="name" autocomplete="name" required>`)}${field('Email address *',`<input id="enquiry-email" name="email" type="email" autocomplete="email" required>`)}${field(wedding?'Occasion date *':'Preferred date *',`<input id="enquiry-date" name="date" type="date" min="${today}" value="${date}" required>`)}${field(wedding?'Time needed *':'Your group size *',wedding?'<input id="enquiry-time" name="time" type="time" value="14:00" required>':'<input id="enquiry-group" name="group" type="number" min="1" max="100" value="2" required>')}${wedding?field('Your preferred car',`<select id="enquiry-car" name="car">${options(['Help me choose','Rolls-Royce','Bentley','Daimler','Cadillac'],booking.car||'Help me choose')}</select>`)+field('Hours needed *','<input id="enquiry-hours" name="hours" type="number" min="1" max="24" value="3" required>'):field('Your interests',`<select id="enquiry-interest" name="interest">${options(['A little of everything','History & culture','Coast & countryside','Food & local life','Photography','Something else'],'A little of everything')}</select>`)+field('Duration',`<select id="enquiry-duration" name="duration">${options(['Half day','Full day','Multiple days','Help me decide'],'Half day')}</select>`)}${field(wedding?'Pickup & venue locations *':'Pickup location *',`<input id="enquiry-pickup" name="pickup" placeholder="${wedding?'Hotel, ceremony venue, reception…':'Hotel or area in Malta'}" required>`,'wide')}${field(wedding?'Tell us about your day':'What would make this your perfect day?',`<textarea id="enquiry-message" name="message" maxlength="1500" placeholder="${wedding?'Preferred style, number of cars, special timings…':'Places you love, interests, accessibility needs, preferred pace…'}"></textarea>`,'wide')}</div>${wedding?'<label class="check-label"><input type="checkbox" name="depositInterest"><span>I’d like the option to pay a deposit once my car and quote are confirmed.</span></label>':''}<label class="check-label"><input type="checkbox" required><span>I agree to be contacted about this enquiry. This preview does not send my details.</span></label><div class="notice">${wedding?'Availability is confirmed by the team; no car is reserved until accepted. Deposit and cancellation terms are agreed with your quote.':'Custom tours are personalised enquiries. Your itinerary and final price are confirmed by the team before booking.'}</div><div class="dialog-actions"><button type="button" class="text-button" data-action="close">← Back to homepage</button><button class="button button-dark" type="submit">${wedding?'Preview availability request':'Preview tour enquiry'} <span>→</span></button></div></form></div>`);}
function enquirySuccess(type,data){booking.enquiry=data;const wedding=type==='wedding';openModal(`<div class="dialog-content"><div class="success-state"><div class="success-icon">✓</div><span class="eyebrow">${wedding?'AVAILABILITY REQUEST · PREVIEW':'TAILOR-MADE ENQUIRY · PREVIEW'}</span><h2 id="dialog-title">${wedding?'A special day deserves a personal touch.':'Let’s find your kind of Malta.'}</h2><p>In the live experience, your enquiry would be sent to the John’s team and acknowledged by email. Nothing has been submitted in this preview.</p><div class="enquiry-success-detail"><strong>${escapeHtml(data.name)}</strong><p>${dateLabel(data.date)} · ${escapeHtml(wedding?data.car:data.interest)}<br>${escapeHtml(data.pickup)}</p></div><p>${wedding?'The next step is staff confirmation of the specific car, availability, total price and deposit terms.':'The next step is a personalised itinerary and quote from the team. Your tour is confirmed after you accept the plan.'}</p>${wedding?'<button class="button button-dark" data-action="deposit">Preview an approved deposit <span>→</span></button>':'<button class="button button-dark" data-action="close">Back to John’s Malta <span>↗</span></button>'}<p class="small-note" style="margin-top:20px">Questions? <a href="tel:+35622982123">+356 2298 2123</a> · info@johns.com.mt</p></div></div>`);}
function showDeposit(){openModal(`<div class="dialog-content"><span class="eyebrow">AFTER STAFF APPROVAL · SAMPLE ONLY</span><h2 id="dialog-title">A little closer to your special day.</h2><p class="intro">This screen demonstrates a payment link sent after the team confirms a car and quote.</p><div class="review-card" style="margin-top:25px"><h3>Vintage wedding car · approved quote preview</h3><div class="price-row"><span>Illustrative package total</span><strong>€600.00</strong></div><div class="price-row"><span>Balance after deposit</span><span>€450.00</span></div><div class="price-row total"><span>Sample deposit due now</span><strong>€150.00</strong></div><p class="small-note">Amounts, deposit percentage, balance due date, VAT and cancellation terms are examples only, pending John’s policy.</p></div><div class="card-preview"><strong>Secure payment through Trust Payments</strong><p>Card · Apple Pay · Google Pay, subject to merchant and device support. This preview collects no financial information.</p></div><div class="dialog-actions"><button class="text-button" data-action="close">Close preview</button><button class="button button-dark" data-action="deposit-done">Preview deposit receipt <span>→</span></button></div></div>`);}
function showManage(){openModal(`<div class="dialog-content"><span class="eyebrow">YOUR JOURNEY, AT A GLANCE</span><h2 id="dialog-title">Find your booking.</h2><p class="intro">No account needed. Your booking reference is in your confirmation email.</p><form id="manage-form"><div class="form-grid">${field('Booking reference *','<input id="booking-reference" name="reference" placeholder="Try JM-DEMO-2601" required>')}${field('Email address *','<input id="booking-email" name="email" type="email" placeholder="Use any example email" required>')}</div><p class="small-note">Demo reference: JM-DEMO-2601. Only a sample status is available; no live customer records are accessed.</p><div class="dialog-actions"><button class="text-button" type="button" data-action="close">← Homepage</button><button class="button button-dark" type="submit">Find my booking <span>→</span></button></div></form></div>`);}
function showFleet(){openModal(`<div class="dialog-content"><span class="eyebrow">SOMETHING FOR EVERY JOURNEY</span><h2 id="dialog-title">Find your kind of comfort.</h2><p class="intro">Compare classes before you travel. Images are from John’s public website. Capacities are illustrative and require fleet confirmation.</p><div class="fleet-modal-grid">${vehicles.map(v=>`<article><img src="assets/${v.img}" alt="${v.name} class"><h3>${v.name}</h3><p>${v.model}<br>Up to ${v.pax} passengers · ${v.bags} large cases<br>Transfer and hourly hire · final vehicle subject to availability</p><button class="underlink" data-fleet-book="${v.id}">Book this class <span>↗</span></button></article>`).join('')}<article><img src="assets/wedding.webp" alt="Vintage wedding car"><h3>Vintage & wedding collection</h3><p>Rolls-Royce · Bentley · Daimler · Cadillac<br>Enquire for specific vehicle, seating and availability.</p><button class="underlink" data-action="wedding">Enquire about a classic <span>↗</span></button></article></div></div>`);}
function showLegal(kind){const contents={privacy:['Your privacy matters.','This is a design demonstration. Booking and enquiry forms do not send information to John’s or an external booking system. Please use sample details.','A production privacy notice must identify the data controller, purposes, legal bases, retention periods, processor arrangements, rights and contact details. This placeholder is not a final privacy policy.','This preview stores only cookie choices and saved tour IDs in local browser storage. Form details are held in memory until the page is refreshed.'],terms:['Clear terms. Confident journeys.','Booking policies will be confirmed with John’s before launch. Final prices, tax treatment, cancellation windows, waiting time, flight delays, luggage limits, extra hours and amendment rules must be shown before checkout.','Wedding and vintage cars require a confirmed quote and vehicle availability. Deposits, balance due dates and refund terms must be agreed before a payment is requested.','This preview creates no contract, booking or payment. Sample fares, capacities, itineraries and deposit values are illustrative.'],cookies:['Your browsing preferences.','Essential storage remembers your privacy choice and tours you save in this preview. No analytics, advertising or tracking scripts run here.','In production, optional GA4 analytics would remain disabled until consent, with a way to withdraw at any time.']};const c=contents[kind];openModal(`<div class="dialog-content legal-content"><span class="eyebrow">JOHN’S MALTA · DESIGN PREVIEW</span><h2 id="dialog-title">${c[0]}</h2>${c.slice(1).map(p=>`<p>${p}</p>`).join('')}${kind==='cookies'?'<div class="dialog-actions"><button class="text-button" data-consent="essential">Essential only</button><button class="button button-dark" data-consent="all">Allow future analytics <span>✓</span></button></div>':'<div class="dialog-actions"><a href="mailto:info@johns.com.mt" class="underlink">Contact John’s <span>↗</span></a><button class="button button-dark" data-action="close">Done <span>✓</span></button></div>'}</div>`);}
function persistPreference(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
function preference(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let savedTours=preference('johns-saved-tours',[]);if(!Array.isArray(savedTours))savedTours=[];
function updateSaveButtons(){$$('[data-save]').forEach(b=>{const saved=savedTours.includes(b.dataset.save);b.setAttribute('aria-pressed',saved);b.textContent=saved?'♥':'♡';});}
document.addEventListener('click',e=>{const btn=e.target.closest('button,a');if(!btn)return;
  if(btn.dataset.tab){setService(btn.dataset.tab);return;}
  if(btn.dataset.route){setService('transfer',true);$('#journey-from').value=locations[0];$('#journey-to').value=btn.dataset.route;notify('Airport route selected. Add your date and passengers.');return;}
  if(btn.dataset.service){closeModal();setService(btn.dataset.service,true);return;}
  if(btn.dataset.tour){showTour(btn.dataset.tour);return;}
  if(btn.dataset.save){const id=btn.dataset.save;if(savedTours.includes(id))savedTours=savedTours.filter(x=>x!==id);else savedTours.push(id);persistPreference('johns-saved-tours',savedTours);updateSaveButtons();notify(savedTours.includes(id)?'Tour saved on this device.':'Tour removed from your saved list.');return;}
  if(btn.dataset.pay){payment=btn.dataset.pay;showCheckout();return;}
  if(btn.dataset.fleetBook){selectedVehicle=btn.dataset.fleetBook;closeModal();setService('transfer',true);notify('Class preference saved. Add your journey to compare availability.');return;}
  if(btn.dataset.consent){persistPreference('johns-consent',{value:btn.dataset.consent,at:new Date().toISOString()});$('#cookie-banner').hidden=true;if(dialog.open)closeModal();notify('Privacy preference saved. No analytics run in this preview.');return;}
  const action=btn.dataset.action;if(!action){if(btn.closest('#mobile-menu')&&btn.tagName==='A'){ $('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}return;}
  const actions={close:closeModal,menu:()=>{const m=$('#mobile-menu');m.hidden=!m.hidden;$('.menu-toggle').setAttribute('aria-expanded',!m.hidden);$('.menu-toggle').setAttribute('aria-label',m.hidden?'Open menu':'Close menu');},manage:showManage,fleet:showFleet,'all-tours':showTours,'custom-tour':()=>showEnquiry('custom'),wedding:()=>showEnquiry('wedding'),'back-vehicles':()=>{saveDetailsDraft();showVehicles();},'back-details':showDetails,receipt:showReceipt,'back-confirmation':()=>showConfirmation(!!booking.pending),deposit:showDeposit,'deposit-done':()=>openModal('<div class="dialog-content"><div class="success-state"><div class="success-icon">✓</div><span class="eyebrow">DEPOSIT RECEIPT · PREVIEW</span><h2 id="dialog-title">A timeless journey awaits.</h2><p>Sample deposit: €150.00 · Sample balance: €450.00.<br>In production, your receipt, confirmed vehicle and balance due date would arrive by email.</p><div class="notice">No deposit has been paid and no vehicle has been reserved.</div><button class="button button-dark" data-action="close">Back to John’s Malta <span>↗</span></button></div></div>'),privacy:()=>showLegal('privacy'),terms:()=>showLegal('terms'),cookies:()=>showLegal('cookies'),'checkout-terms':()=>{const existing=$('#checkout-inline-terms');if(existing){existing.remove();return;}btn.closest('form').insertAdjacentHTML('afterbegin','<div id="checkout-inline-terms" class="notice">Demo only. Production checkout must disclose cancellation and amendment windows, waiting charges, flight-delay policy and the final VAT-inclusive price. No payment is taken in this preview.</div>');}};actions[action]?.();
});
document.addEventListener('change',e=>{if(e.target.name==='direction'){captureJourneyDraft();direction=e.target.value;renderFields();}if(e.target.id==='luggage-count'){booking.bags=Number(e.target.value);showVehicles();}if(e.target.name==='invoice'){const show=e.target.checked;$('#invoice-fields').hidden=!show;$$('input',$('#invoice-fields')).forEach(x=>x.required=show);}});
function saveDetailsDraft(){const f=$('#details-form');if(!f)return;const data=Object.fromEntries(new FormData(f));booking={...booking,...data,extraHours:Number(data.extraHours||0),childSeat:!!data.childSeat,booster:!!data.booster,invoice:!!data.invoice};}
document.addEventListener('submit',e=>{const f=e.target;e.preventDefault();if(!f.checkValidity()){f.reportValidity();return;}const data=Object.fromEntries(new FormData(f));
 if(f.id==='journey-form'){
  const pax=parseInt(data.passengers)||2;booking={...data,service,passengers:pax,direction:service==='transfer'?direction:'one-way',hours:parseInt(data.hours)||0,bags:1,time:data.time||'09:00'};
  if(booking.date<today){notify('Please choose today or a future date.');return;}
  if(service==='transfer'&&booking.from.toLowerCase()===booking.to.trim().toLowerCase()){notify('Choose different pickup and destination locations.');$('#journey-to').focus();return;}
  if(booking.direction==='return'&&new Date(booking.returnDate+'T'+booking.returnTime)<=new Date(booking.date+'T'+booking.time)){notify('Your return must be after your outward journey.');$('#return-date').focus();return;}
  if(service==='wedding'){showEnquiry('wedding');return;}if(service==='tour'){if(data.tour==='custom')showEnquiry('custom');else showTour(data.tour);return;}showVehicles();
 }else if(f.id==='vehicle-form'){selectedVehicle=data.vehicle;showDetails();}
 else if(f.id==='details-form'){saveDetailsDraft();showCheckout();}
 else if(f.id==='checkout-form'){booking.pending=$('#pending-preview').checked;showConfirmation(booking.pending);}
 else if(f.id==='tour-book-form'){booking={...data,service:'tour',tour:chosenTour,passengers:Number(data.passengers),bags:1,direction:'one-way'};showVehicles();}
 else if(f.id==='enquiry-form'){enquirySuccess(f.dataset.type,data);}
 else if(f.id==='manage-form'){
  if(data.reference.trim().toUpperCase()!=='JM-DEMO-2601'){let error=$('.inline-error',f);if(!error){error=document.createElement('span');error.className='inline-error';error.setAttribute('role','alert');f.prepend(error);}error.textContent='No sample booking found. Try JM-DEMO-2601, or contact the team.';return;}
  openModal(`<div class="dialog-content"><span class="eyebrow">YOUR SAMPLE BOOKING</span><h2 id="dialog-title">Everything in one place.</h2><div class="reference" style="margin:25px 0">BOOKING REFERENCE<strong>JM-DEMO-2601</strong>Confirmed · demonstration only</div><div class="review-card"><h3>Malta Airport → Valletta</h3><p class="small-note">Executive vehicle · 2 passengers · 1 suitcase<br>Meet & greet at airport arrivals<br>Sample status: awaiting driver assignment</p></div><div class="notice">In production, status updates come from codevlabs. Amendments and cancellations follow your service’s terms. This screen shows no live booking or customer details.</div><div class="dialog-actions"><button class="text-button" data-action="manage">← Find another booking</button><a class="button button-dark" href="tel:+35622982123">Contact our team <span>↗</span></a></div></div>`);
 }
});
$('.service-tabs').addEventListener('keydown',e=>{const tabs=$$('[data-tab]');const index=tabs.indexOf(e.target);let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();setService(tabs[next].dataset.tab);tabs[next].focus();});
hydrateIcons();setService('transfer');updateSaveButtons();if(!preference('johns-consent',null))$('#cookie-banner').hidden=false;
